CREATE TABLE ownership (instance_id TEXT PRIMARY KEY, container_id TEXT NOT NULL, container_name TEXT NOT NULL, network_name TEXT NOT NULL, image_digest TEXT NOT NULL, data_path TEXT NOT NULL, created_at TEXT NOT NULL, runtime_generation INTEGER NOT NULL DEFAULT 1, application_id TEXT NOT NULL, release_id TEXT NOT NULL, exposure_mode TEXT NOT NULL DEFAULT 'internal', service_id TEXT NOT NULL DEFAULT '', host_address TEXT NOT NULL DEFAULT '', host_port INTEGER NOT NULL DEFAULT 0, container_port INTEGER NOT NULL DEFAULT 0, service_protocol TEXT NOT NULL DEFAULT '');
CREATE TABLE receipts (operation_id TEXT PRIMARY KEY, request_hash TEXT NOT NULL, operation_type TEXT NOT NULL, instance_id TEXT NOT NULL, phase TEXT NOT NULL, outcome TEXT NOT NULL, container_id TEXT, created_at TEXT NOT NULL);
